 interface Task{void run()throws Exception;}
 void attempt(Task task){try{task.run();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Could not finish this action").setMessage("Your last saved progress is retained. "+e.getClass().getSimpleName()).setPositiveButton("OK",null).show();}}
 @Override protected void attachBaseContext(Context base){android.content.res.Configuration config=new android.content.res.Configuration(base.getResources().getConfiguration());config.setLocale(Locale.ENGLISH);String mode=base.getSharedPreferences("appearance",0).getString("mode","system");if(!mode.equals("system"))config.uiMode=(config.uiMode&~android.content.res.Configuration.UI_MODE_NIGHT_MASK)|(mode.equals("dark")?android.content.res.Configuration.UI_MODE_NIGHT_YES:android.content.res.Configuration.UI_MODE_NIGHT_NO);super.attachBaseContext(base.createConfigurationContext(config));}
 @Override public void onCreate(Bundle b){super.onCreate(b);INK=getColor(res("color","juicyEel"));GREY=getColor(res("color","juicySwan"));try{regular=Typeface.createFromAsset(getAssets(),"fonts/duolingosans_regular.otf");bold=Typeface.createFromAsset(getAssets(),"fonts/duolingosans_bold.otf");String account=getPreferences(0).getString("google-account","");engine=new Engine(this,account.isEmpty()?"progress-v1.json":"progress-google-"+GoogleProgress.accountKey(account)+".json");updates=new com.inhouse.services.updater.NativeUpdates(this);cloud=new GoogleProgress(this);bindProgress();if(account.isEmpty())showSignIn();else if(engine.session()!=null)quiz();else home();handleOAuth(getIntent());}catch(Exception e){TextView t=new TextView(this);t.setText("Unable to open the local course: "+e.getMessage());setContentView(t);}}
