 void path()throws Exception{
  View hero=getLayoutInflater().inflate(res("layout","duoaero_course_header"),body,false);spaced(body,hero);
  if(engine.session()!=null)spaced(body,button("Resume lesson",true,()->quiz()));
  for(int u=0;u<units.length;u++){View heading=getLayoutInflater().inflate(res("layout","view_path_basic_unit_header"),body,false);((TextView)heading.findViewById(res("id","headerText"))).setText("Unit "+(u+1)+" · "+units[u][1]);add(body,heading);int pos=0;for(int i=0;i<engine.nodes.length();i++){JSONObject node=engine.nodes.getJSONObject(i);if(!node.getString("topic").equals(units[u][0]))continue;LinearLayout line=row();int[] shifts={0,14,28,14};line.setPadding(dp(shifts[pos++%4]),dp(12),0,dp(12));FrameLayout nodeView=new FrameLayout(this);RingView ring=new RingView(node);ring.drawFace=false;nodeView.addView(ring,new FrameLayout.LayoutParams(-1,-1));View face=getLayoutInflater().inflate(res("layout","duoaero_path_button"),nodeView,false);FrameLayout.LayoutParams faceParams=new FrameLayout.LayoutParams(dp(74),dp(74),Gravity.CENTER);nodeView.addView(face,faceParams);face.setContentDescription("Start "+node.getString("name"));face.setOnClickListener(v->attempt(()->{JSONObject lesson=engine.nextLesson(node);engine.start(engine.strings(lesson.getJSONArray("ids")),lesson.getString("name"),"pathlesson",lesson.getString("id"));openLesson();}));line.addView(nodeView,new LinearLayout.LayoutParams(dp(116),dp(116)));TextView label=text(node.getString("name"),16,true);label.setPadding(dp(12),0,0,0);line.addView(label,new LinearLayout.LayoutParams(0,-2,1));add(body,line);}}
 }
 final class RingView extends View{
  boolean drawFace=true;final JSONObject node;final Paint p=new Paint(3);RingView(JSONObject n){super(MainActivity.this);node=n;setFocusable(true);setClickable(true);}
  @Override protected void onDraw(Canvas c){super.onDraw(c);float scale=Math.min(getWidth(),getHeight())/124f;c.save();c.translate((getWidth()-124*scale)/2,(getHeight()-124*scale)/2);c.scale(scale,scale);try{JSONArray ls=node.getJSONArray("lessons");p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(8);p.setStrokeCap(Paint.Cap.ROUND);for(int i=0;i<ls.length();i++){p.setColor(engine.done(ls.getJSONObject(i))?GREEN:GREY);if(ls.length()==1)c.drawCircle(62,62,51,p);else c.drawArc(new RectF(11,11,113,113),-90+i*360f/ls.length()+8,360f/ls.length()-16,false,p);}if(!drawFace){c.restore();return;}p.setStyle(Paint.Style.FILL);p.setColor(0xff58a700);c.drawCircle(62,62,39,p);p.setColor(isPressed()?0xff85d23d:0xff7ac932);c.drawOval(new RectF(23,23,101,95),p);Path star=new Path();for(int i=0;i<10;i++){double a=-Math.PI/2+i*Math.PI/5;float r=i%2==0?20:10.5f,x=62+(float)Math.cos(a)*r,y=59+(float)Math.sin(a)*r;if(i==0)star.moveTo(x,y);else star.lineTo(x,y);}star.close();p.setColor(Color.WHITE);p.setPathEffect(new CornerPathEffect(3));c.drawPath(star,p);p.setPathEffect(null);}catch(Exception ignored){}c.restore();}
 }
 void review()throws Exception{List<String> ids=engine.mistakes();View header=getLayoutInflater().inflate(res("layout","duoaero_review_header"),body,false);((TextView)header.findViewById(res("id","title"))).setText(ids.isEmpty()?"All caught up!":"Review mistakes");TextView start=header.findViewById(res("id","startButton"));start.setText(ids.isEmpty()?"NO PREVIOUS MISTAKES":"REVIEW MISTAKES");start.setEnabled(!ids.isEmpty());start.setOnClickListener(v->attempt(()->{engine.start(ids,"Review mistakes","review","");openLesson();}));add(body,header);if(ids.isEmpty()){mascot(body,"celebrate",220);add(body,text("Unresolved lesson mistakes will appear here until corrected.",16,false));}for(String id:ids){JSONObject q=engine.questions.get(id);View card=getLayoutInflater().inflate(res("layout","mistakes_collection_mistake"),body,false);((TextView)card.findViewById(res("id","mistakeInstruction"))).setText(stars(q)+"  PREVIOUS MISTAKE");((TextView)card.findViewById(res("id","mistakeSentence"))).setText(q.getString("stem"));card.setOnClickListener(v->attempt(()->{engine.start(Collections.singletonList(id),"Previous mistake","review","");openLesson();}));spaced(body,card);}}

 String stars(JSONObject q){int d=q.optInt("difficulty");return d==3?"★★★":d==2?"★★☆":"★☆☆";}
 void library()throws Exception{
  add(body,text("Questions",28,true));LinearLayout filters=row();Spinner levels=spinner(new String[]{"All levels","★","★★","★★★"},difficulty),sources=spinner(new String[]{"All sources","Past exams","Think at home","Practice"},origin),years=spinner(new String[]{"All years","2019","2021","2022","2023","2025"},year);filters.addView(levels,new LinearLayout.LayoutParams(0,-2,1));filters.addView(sources,new LinearLayout.LayoutParams(0,-2,1));filters.addView(years,new LinearLayout.LayoutParams(0,-2,1));add(body,filters);
  EditText input=(EditText)getLayoutInflater().inflate(res("layout","duoaero_input"),body,false);input.setSingleLine(true);input.setHint("Search questions");input.setText(search);add(body,input);LinearLayout list=column();add(body,list);
  Runnable refresh=()->attempt(()->{difficulty=String.valueOf(levels.getSelectedItem());origin=String.valueOf(sources.getSelectedItem());year=String.valueOf(years.getSelectedItem());search=input.getText().toString();fillLibrary(list);});
  AdapterView.OnItemSelectedListener listener=new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){shown=100;refresh.run();}public void onNothingSelected(AdapterView<?> p){}};levels.setOnItemSelectedListener(listener);sources.setOnItemSelectedListener(listener);years.setOnItemSelectedListener(listener);
  input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){shown=100;refresh.run();}public void afterTextChanged(Editable e){}});refresh.run();
 }
 Spinner spinner(String[] values,String selected){Spinner s=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,values){public View getView(int position,View recycled,android.view.ViewGroup parent){TextView label=text(getItem(position),15,false);label.setPadding(dp(8),dp(10),dp(8),dp(10));label.setMinHeight(dp(48));label.setSingleLine(false);label.setEllipsize(null);return label;}public View getDropDownView(int position,View recycled,android.view.ViewGroup parent){return getView(position,recycled,parent);}};adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(adapter);for(int i=0;i<values.length;i++)if(values[i].equals(selected))s.setSelection(i);return s;}
 void fillLibrary(LinearLayout list)throws Exception{list.removeAllViews();List<String> ids=new ArrayList<>();String kind=origin.equals("Past exams")?"exam":origin.equals("Think at home")?"reflection":origin.equals("Practice")?"practice":"";for(JSONObject q:engine.questions.values()){JSONObject o=q.getJSONObject("origin");if(!difficulty.equals("All levels")&&q.getInt("difficulty")!=difficulty.length())continue;if(!kind.isEmpty()&&!o.optString("kind").equals(kind))continue;if(!year.equals("All years")&&!o.optString("date").startsWith(year))continue;if(!(q.getString("stem")+o.optString("title")).toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT)))continue;ids.add(q.getString("id"));}
  add(list,text(ids.size()+" questions",14,false));if(!ids.isEmpty())spaced(list,button("Practise selection",true,()->{engine.start(ids,"Question practice","practice","");openLesson();}));for(int i=0;i<Math.min(shown,ids.size());i++){String id=ids.get(i);JSONObject q=engine.questions.get(id),o=q.getJSONObject("origin");String caption=stars(q)+(o.optString("kind").equals("exam")?" · EXAM QUESTION\n"+o.optString("date")+" · Q"+o.optString("number")+"\n":"\n")+q.getString("stem");spaced(list,answerCard(caption,false,false,false,false,()->{engine.start(Collections.singletonList(id),"Question practice","practice","");openLesson();}));}if(shown<ids.size())spaced(list,button("Show more",false,()->{shown+=100;fillLibrary(list);}));
 }
 void settings()throws Exception{spaced(body,button("Appearance",false,()->new AlertDialog.Builder(this).setTitle("Appearance").setItems(new String[]{"System default","Light","Dark"},(dialog,which)->{getSharedPreferences("appearance",0).edit().putString("mode",new String[]{"system","light","dark"}[which]).apply();recreate();}).show()));spaced(body,button("App updates",false,()->startActivity(new Intent(this,com.inhouse.services.updater.UpdateActivity.class).putExtra("settings",true))));cloudStatus=text(cloud.status,14,false);add(body,cloudStatus);spaced(body,button(getPreferences(0).getString("google-label","GOOGLE ACCOUNT"),false,()->cloud.signIn()));if(!getPreferences(0).getString("google-account","").isEmpty())spaced(body,button("Sign out",false,()->cloud.signOut()));add(body,text("Settings",28,true));for(String key:new String[]{"sound","haptics","motion"}){View preference=getLayoutInflater().inflate(res("layout","preference_material"),body,false);TextView caption=preference.findViewById(android.R.id.title);caption.setText(key.equals("sound")?"Lesson sounds":key.equals("haptics")?"Haptic feedback":"Animations");caption.setSingleLine(false);caption.setTextColor(INK);caption.setTypeface(regular);preference.findViewById(android.R.id.summary).setVisibility(View.GONE);android.view.ViewGroup widget=preference.findViewById(android.R.id.widget_frame);CompoundButton toggle=(CompoundButton)getLayoutInflater().inflate(res("layout","preference_widget_switch_compat"),widget,false);toggle.setClickable(true);widget.addView(toggle);toggle.setChecked(engine.settings().optBoolean(key,true));toggle.setOnCheckedChangeListener((v,on)->attempt(()->{engine.settings().put(key,on);engine.save();}));preference.setOnClickListener(v->toggle.setChecked(!toggle.isChecked()));add(body,preference);}add(body,text("Progress is saved automatically on this device.",16,false));add(body,text("DuoAero 1.2.0\n1,200 questions · Midterm 1",14,false));spaced(body,button("Sources and reference assets",false,()->new AlertDialog.Builder(this).setTitle("Sources and reference assets").setMessage("Each question contains its source and exam attribution. Answers are derived where the official key was not retained.\n\nSelected layout code, fonts, icons, sounds and transitions are adapted from the APK supplied by you. The course engine and local progress system are implemented for DuoAero.\n\n2022 Q13 retains the original excerpt; its unrecoverable measured stall angle is not fabricated.").setPositiveButton("OK",null).show()));}
 void openLesson(){inQuiz=true;shell();View loading=getLayoutInflater().inflate(res("layout","duoaero_loading"),root,false);root.addView(loading,new LinearLayout.LayoutParams(-1,0,1));LinearLayout loadingRoot=root;loading.postDelayed(()->{if(root==loadingRoot&&!isFinishing()&&!isDestroyed())attempt(()->quiz());},motion()?500:1);}
 View answerCard(String label,boolean selected,boolean positive,boolean negative,boolean showCheck,Task action)throws Exception{View card=getLayoutInflater().inflate(res("layout","duoaero_answer"),body,false);TextView text=card.findViewById(res("id","optionName"));text.setText(clean(label));text.setSingleLine(false);text.setMaxLines(Integer.MAX_VALUE);text.setEllipsize(null);text.setTextColor(INK);card.findViewById(res("id","check")).setVisibility(showCheck?View.VISIBLE:View.GONE);card.setSelected(selected);if(selected||positive||negative){int color=getColor(res("color",positive?"juicySeaSponge":negative?"juicyWalkingFish":"juicyIguana"));android.util.Property property=(android.util.Property)card.getClass().getMethod("getFaceColorProperty").invoke(card);property.set(card,color);}card.setOnClickListener(action==null?null:v->{hapticPreset("cta_button_v3");attempt(action);});return card;}
 void quiz()throws Exception{inQuiz=true;
  if(engine.session()==null){home();return;}if(engine.ended()){completion();return;}
  shell();View layout=getLayoutInflater().inflate(res("layout","duoaero_session"),root,false);root.addView(layout,new LinearLayout.LayoutParams(-1,-1));body=layout.findViewById(res("id","aero_element_container"));footer=layout.findViewById(res("id","aero_feedback"));layout.findViewById(res("id","quitButton")).setOnClickListener(v->attempt(()->{engine.save();screen="learn";home();}));JSONObject s=engine.session(),q=engine.current();JSONArray order=engine.order(q);View progress=layout.findViewById(res("id","progress"));progress.getClass().getMethod("setProgress",float.class).invoke(progress,(float)s.getJSONArray("awarded").length()/s.getJSONArray("ids").length());boolean retry=s.getInt("cursor")>=s.getJSONArray("ids").length()||s.getString("kind").equals("review"),checked=s.optBoolean("checked");JSONObject source=q.getJSONObject("origin");
  LinearLayout labels=row();if(source.optString("kind").equals("exam")){ImageView icon=new ImageView(this);icon.setImageResource(res("drawable","hard_exercise"));labels.addView(icon,new LinearLayout.LayoutParams(dp(24),dp(24)));TextView exam=text("  EXAM QUESTION",14,true);exam.setTextColor(PURPLE);labels.addView(exam);}else if(source.optString("kind").equals("reflection"))labels.addView(text("THINK AT HOME",14,true));TextView star=text(stars(q),18,true);star.setTextColor(0xffe8ac00);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,-2,1);star.setGravity(Gravity.END);labels.addView(star,sp);add(body,labels);if(retry){TextView tag=text("↻ PREVIOUS MISTAKE",14,true);tag.setTextColor(PURPLE);add(body,tag);}add(body,text(q.getString("stem"),22,true));String type=q.getString("type");add(body,text(type.equals("multi")?"Select all correct answers.":type.equals("gap")?"Complete with one word.":type.equals("order")?"Put the steps in order.":type.equals("matching")?"Match every pair.":"Choose one answer.",15,false));
  TextView check=button(checked?"CONTINUE":"CHECK",true,()->{if(engine.session().optBoolean("checked")){engine.advance();quiz();}else if(engine.check()){boolean ok=engine.session().optBoolean("correct");int combo=engine.session().optInt("combo");play(ok?(combo>0&&combo%10==0?"combo10":combo>0&&combo%5==0?"combo5":"correct"):"wrong");haptic(ok);quiz();}});
  if(type.equals("choice")||type.equals("multi")){for(int j=0;j<order.length();j++){final int i=order.getInt(j);boolean selected=type.equals("choice")?s.optInt("answer",-1)==i:contains(s.optJSONArray("answer"),i),correct=type.equals("choice")?q.getInt("answer")==i:contains(q.getJSONArray("answer"),i);Task select=()->{if(type.equals("choice"))engine.select(i);else{JSONArray a=engine.session().optJSONArray("answer"),n=new JSONArray();boolean had=contains(a,i);for(int k=0;a!=null&&k<a.length();k++)if(a.getInt(k)!=i)n.put(a.getInt(k));if(!had)n.put(i);engine.select(n);}quiz();};spaced(body,answerCard(q.getJSONArray("options").getString(i),selected,checked&&correct,checked&&selected&&!correct,type.equals("multi")&&selected,checked?null:select));}}

  else if(type.equals("gap")){EditText input=(EditText)getLayoutInflater().inflate(res("layout","duoaero_input"),body,false);input.setSingleLine(true);input.setText(s.optString("answer",""));input.setEnabled(!checked);input.setHint("Missing word");input.setTypeface(regular);add(body,input);input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence a,int b,int c,int d){}public void onTextChanged(CharSequence a,int b,int c,int d){attempt(()->{engine.select(a.toString());check.setEnabled(engine.ready(q,engine.session().opt("answer")));});}public void afterTextChanged(Editable a){}});}
  else if(type.equals("order")){if(!s.has("answer"))s.put("answer",new JSONArray(order.toString()));JSONArray a=s.getJSONArray("answer");for(int j=0;j<a.length();j++){final int pos=j;LinearLayout line=row();TextView item=text((j+1)+". "+q.getJSONArray("items").getString(a.getInt(j)),16,false);line.addView(item,new LinearLayout.LayoutParams(0,-2,1));for(int delta:new int[]{-1,1}){TextView move=button(delta<0?"↑":"↓",false,()->{JSONArray ar=engine.session().getJSONArray("answer");int temp=ar.getInt(pos);ar.put(pos,ar.getInt(pos+delta));ar.put(pos+delta,temp);engine.select(ar);quiz();});move.setContentDescription("Move step "+(j+1)+(delta<0?" up":" down"));move.setEnabled(!checked&&pos+delta>=0&&pos+delta<a.length());line.addView(move,new LinearLayout.LayoutParams(dp(48),dp(52)));}spaced(body,line);}}
  else if(type.equals("matching")){JSONArray pairs=q.getJSONArray("pairs");String question=q.getString("id");if(!matchingQuestion.equals(question)){matchingQuestion=question;matchingFrom=-1;}if(!s.has("answer")){JSONArray initial=new JSONArray();for(int i=0;i<pairs.length();i++)initial.put(-1);s.put("answer",initial);}for(int j=0;j<pairs.length();j++){final int left=j,right=order.getInt(j);JSONArray answers=s.getJSONArray("answer");int linked=-1;for(int k=0;k<answers.length();k++)if(answers.optInt(k,-1)==right)linked=k;LinearLayout pair=row();View l=answerCard((left+1)+". "+pairs.getJSONArray(left).getString(0),matchingFrom==left,checked&&answers.optInt(left)==left,checked&&answers.optInt(left)!=left,false,checked?null:()->{matchingFrom=left;quiz();});View r=answerCard((linked>=0?"["+(linked+1)+"] ":"")+pairs.getJSONArray(right).getString(1),linked>=0,checked&&linked==right,checked&&linked>=0&&linked!=right,false,checked?null:()->{if(matchingFrom<0)return;JSONArray ar=engine.session().getJSONArray("answer");for(int k=0;k<ar.length();k++)if(ar.optInt(k,-1)==right)ar.put(k,-1);ar.put(matchingFrom,right);engine.select(ar);matchingFrom=-1;quiz();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,0,dp(6),0);pair.addView(l,lp);pair.addView(r,new LinearLayout.LayoutParams(0,-2,1));spaced(body,pair);}}

  String attribution=source.optString("kind").equals("exam")?"Exam: "+source.optString("date")+" · Model "+source.optString("model")+" · Question "+source.optString("number"):source.optString("kind").equals("reflection")?"Think at home · Slide "+source.optString("slide"):"Practice · Course material";add(body,text(attribution,13,true));if(source.optBoolean("adapted"))add(body,text("Translated or adapted for practice. Original wording below.",13,false));spaced(body,button("Source and original wording",false,()->new AlertDialog.Builder(this).setTitle(source.optString("title")).setMessage(source.optString("answer_basis","")+"\n\n"+source.optString("source_excerpt",q.optString("explanation"))).setPositiveButton("Open source",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(source.optString("url"))));}catch(Exception ignored){}}).setNegativeButton("Close",null).show()));
  if(checked){boolean ok=s.optBoolean("correct");footer.setBackgroundColor(ok?getColor(res("color","juicySeaSponge")):getColor(res("color","juicyWalkingFish")));add(footer,text(ok?(retry?"Mistake corrected!":"Nicely done!"):"Let's learn from this",20,true));ScrollView feedbackScroll=new ScrollView(this);LinearLayout explanation=column();if(!ok)add(explanation,text("Correct answer: "+engine.solution(q),15,true));add(explanation,text(q.getString("explanation"),15,false));feedbackScroll.addView(explanation);footer.addView(feedbackScroll,new LinearLayout.LayoutParams(-1,dp(110)));JSONObject explanations=q.optJSONObject("option_explanations");if(explanations!=null)spaced(body,button("Why the alternatives differ",false,()->{StringBuilder t=new StringBuilder();JSONArray options=q.getJSONArray("options");for(int i=0;i<options.length();i++){String option=options.getString(i);t.append(option).append("\n").append(explanations.optString(option,explanations.optString(String.valueOf((char)('A'+i)),q.optString("explanation")))).append("\n\n");}new AlertDialog.Builder(this).setTitle("Answer explanations").setMessage(t.toString()).setPositiveButton("OK",null).show();}));if(motion())footer.startAnimation(AnimationUtils.loadAnimation(this,res("anim","adventures_slide_in_bottom")));}
  check.setEnabled(checked||engine.ready(q,s.opt("answer")));add(footer,check);engine.save();
 }
 boolean contains(JSONArray a,int v){for(int i=0;a!=null&&i<a.length();i++)if(a.optInt(i,-1)==v)return true;return false;}
 void completion()throws Exception{shell();JSONObject session=engine.session();int first=0;Iterator<String> it=session.getJSONObject("initialResults").keys();while(it.hasNext())if(session.getJSONObject("initialResults").optBoolean(it.next()))first++;int total=session.getJSONArray("ids").length();boolean perfect=first==total;View view=getLayoutInflater().inflate(res("layout","duoaero_complete"),root,false);((TextView)view.findViewById(res("id","title"))).setText(perfect?"Perfect lesson!":"Lesson complete!");((TextView)view.findViewById(res("id","subtitle"))).setText("Every mistake corrected");ImageView mascot=view.findViewById(res("id","lottieView"));try{mascot.setImageDrawable(Drawable.createFromStream(getAssets().open("mascot/celebrate.png"),null));}catch(Exception ignored){}String[] labels={"ACCURACY","QUESTIONS","RETRIES"},values={Math.round(100f*first/total)+"%",String.valueOf(total),String.valueOf(session.getJSONArray("queue").length()-total)};for(int i=0;i<3;i++){View card=view.findViewById(res("id","statCard"+(i+1)));card.setAlpha(1);View statFace=card.findViewById(res("id","cardView"));android.view.ViewGroup.MarginLayoutParams statParams=(android.view.ViewGroup.MarginLayoutParams)statFace.getLayoutParams();statParams.topMargin=dp(24);statFace.setLayoutParams(statParams);((ImageView)card.findViewById(res("id","statImageView"))).setImageResource(res("drawable",new String[]{"path_star_filled","tab_redesign_tab_goals","tab_redesign_tab_bar_practice_hub"}[i]));((TextView)card.findViewById(res("id","tokenText"))).setText(labels[i]);View ticker=card.findViewById(res("id","statTickerView"));android.view.ViewGroup parent=(android.view.ViewGroup)ticker.getParent();int index=parent.indexOfChild(ticker);android.view.ViewGroup.LayoutParams params=ticker.getLayoutParams();parent.removeView(ticker);TextView value=text(values[i],20,true);value.setId(res("id","statTickerView"));parent.addView(value,index,params);if(motion()){card.setAlpha(0);card.animate().alpha(1).setStartDelay(i*160).setDuration(250).start();}}root.addView(view,new LinearLayout.LayoutParams(-1,0,1));view.findViewById(res("id","continueButtonView")).setOnClickListener(v->attempt(()->{engine.leave();screen="learn";home();}));if(!session.optBoolean("celebrated")){session.put("celebrated",true);engine.save();play(perfect?"perfect":"complete");hapticPreset(perfect?"perfect_lesson_duo_v2":"lessoncomplete_v6");}}

 boolean motion(){return engine.settings().optBoolean("motion",true)&&Settings.Global.getFloat(getContentResolver(),Settings.Global.ANIMATOR_DURATION_SCALE,1f)>0;}
 void play(String name){if(!engine.settings().optBoolean("sound",true))return;try{if(player!=null){player.release();player=null;}android.content.res.AssetFileDescriptor a=getAssets().openFd("audio/"+name+".mp3");player=new MediaPlayer();player.setDataSource(a.getFileDescriptor(),a.getStartOffset(),a.getLength());a.close();player.setAudioAttributes(new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_GAME).setContentType(android.media.AudioAttributes.CONTENT_TYPE_SONIFICATION).build());player.setVolume(1f,1f);player.prepare();player.setOnCompletionListener(p->{p.release();if(player==p)player=null;});player.start();}catch(Exception error){android.util.Log.e("DuoAeroAudio","Cannot play lesson sound: "+name,error);if(player!=null){player.release();player=null;}}}
 void haptic(boolean correct){hapticPreset(correct?"flashcards_correct_haptic":"flashcards_final_incorrect_haptic");}
 void hapticPreset(String name){if(!engine.settings().optBoolean("haptics",true))return;try{Vibrator vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);if(vibrator==null||!vibrator.hasVibrator())return;String level=vibrator.hasAmplitudeControl()?"_l2":"_l1";int id=res("raw",name+level);if(id==0)throw new IllegalArgumentException("Missing original haptic "+name);java.io.InputStream stream=getResources().openRawResource(id);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[1024];int n;while((n=stream.read(buffer))!=-1)bytes.write(buffer,0,n);stream.close();JSONObject preset=new JSONObject(bytes.toString("UTF-8"));JSONArray ts=preset.getJSONArray("Timings"),as=preset.getJSONArray("Amplitudes");long[] timings=new long[ts.length()];int[] amplitudes=new int[as.length()];for(int i=0;i<timings.length;i++){timings[i]=ts.getLong(i);amplitudes[i]=as.getInt(i);}vibrator.vibrate(VibrationEffect.createWaveform(timings,amplitudes,-1),new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_ASSISTANCE_SONIFICATION).build());}catch(Exception error){android.util.Log.e("DuoAeroHaptics","Original haptic unavailable",error);}}

 @Override public void onBackPressed(){attempt(()->{if(inQuiz){engine.save();screen="learn";home();}else if(!screen.equals("learn")){screen="learn";home();}else super.onBackPressed();});}
 @Override protected void onResume(){super.onResume();if(updates!=null)updates.onResumed(this);}
 @Override protected void onPause(){if(updates!=null)updates.onPaused(this);super.onPause();if(engine!=null)try{engine.save();}catch(Exception ignored){}}
 @Override protected void onDestroy(){if(updates!=null)updates.onDestroyed(this);if(player!=null){player.release();player=null;}if(cloud!=null)cloud.close();super.onDestroy();}
